  function kitOf(cfg, has, str) {
    const bal = cfg.bal ?? {};
    const sk = cfg.skills ?? {};
    const ails = (o) => {
      const out = /* @__PURE__ */ new Set();
      const walk = (v) => {
        if (Array.isArray(v)) v.forEach(walk);
        else if (v && typeof v === "object") {
          const d3 = v.debuff;
          if (d3?.k) out.add(d3.k);
          Object.values(v).forEach(walk);
        }
      };
      walk(o);
      return [...out];
    };
    const skill = ails([sk.skill, sk.skill2]), charge2 = ails(sk.charge), sup = ails(sk.super);
    return {
      shot: has("15") && bal.gun !== "none",
      thrown: bal.gun === "thrown",
      hot: !!cfg.ranged?.heat || bal.gun === "rapid",
      skill: !!sk.skill,
      charge: !!sk.charge,
      super: !!sk.super,
      str,
      ails: { skill, charge: charge2, super: sup, any: [.../* @__PURE__ */ new Set([...skill, ...charge2, ...sup])] }
    };
  }
